  client-side input. Sensitive values are never browser-console logged.
*/
const ACADEMIC_TEST_OUTPUT_ENABLED = Bun.env.MFA_ACADEMIC_TEST_OUTPUT === "true";

type Session = { userId: string; csrf: string; createdAt: number; lastSeenAt: number };
type Account = {
  id: string;
