<script nonce="${nonce}">
"use strict";
const app=document.querySelector("#app");
const TEST_MOCK_LOGGING=${TEST_MOCK_LOGGING ? "true" : "false"};
let csrf="",secretValue="",uri="",codes=[];

/*
 Requirement task: This is deliberately off in normal operation. When a
 controlled test server is started with MFA_TEST_MOCK_LOGGING=1, test values
 go only to the browser developer console and are never inserted into the DOM.
*/
function testOnlyLog(label,value){
