}

/*
 Requirement task: standards-compliant QR Model 2 encoder.
 It creates a Version 10, error-correction L QR code in byte mode. Version 10-L
 has 274 data codewords, enough for this exact otpauth provisioning URI.
 Reed-Solomon blocks, masking, format information, finder/alignment/timing
 patterns, and quiet zone are all generated locally with no external asset.
*/
function qr(text){
  const bytes=new TextEncoder().encode(text);
  const size=57, dataCapacity=274, blocks=[[68,18],[68,18],[69,18],[69,18]];
  if(bytes.length>dataCapacity-2) throw new Error("Setup link is too long.");

  const gfExp=new Uint8Array(512),gfLog=new Uint8Array(256);
  let x=1;
  for(let i=0;i<255;i++){gfExp[i]=x;gfLog[x]=i;x<<=1;if(x&256)x^=0x11d}
  for(let i=255;i<512;i++)gfExp[i]=gfExp[i-255];
  const mul=(a,b)=>a&&b?gfExp[gfLog[a]+gfLog[b]]:0;
  function poly(ec){
    let p=[1];
    for(let i=0;i<ec;i++){
      const next=new Array(p.length+1).fill(0);
      for(let j=0;j<p.length;j++){next[j]^=p[j];next[j+1]^=mul(p[j],gfExp[i])}
      p=next;
    }
    return p;
  }
  function remainder(data,ec){
    const g=poly(ec), out=new Uint8Array(ec);
    for(const byte of data){
      const factor=byte^out[0];
      out.copyWithin(0,1);out[ec-1]=0;
      for(let i=0;i<ec;i++)out[i]^=mul(g[i+1],factor);
    }
    return [...out];
  }
  const payload=[0x40,bytes.length,...bytes];
  while(payload.length<dataCapacity)payload.push(payload.length%2?0x11:0xec);
  const chunks=[], ecc=[];
  let offset=0;
  for(const [length,ec] of blocks){
    const part=payload.slice(offset,offset+length);offset+=length;
    chunks.push(part);ecc.push(remainder(part,ec));
  }
  const stream=[];
  for(let i=0;i<69;i++)for(const part of chunks)if(i<part.length)stream.push(part[i]);
  for(let i=0;i<18;i++)for(const part of ecc)stream.push(part[i]);

  function baseMatrix(){
    const m=Array.from({length:size},()=>Array(size).fill(null));
    const set=(r,c,v)=>{if(r>=0&&r<size&&c>=0&&c<size)m[r][c]=v};
    function finder(r,c){
      for(let y=-1;y<=7;y++)for(let z=-1;z<=7;z++)
        set(r+y,c+z,y>=0&&y<=6&&z>=0&&z<=6&&(y===0||y===6||z===0||z===6||(y>=2&&y<=4&&z>=2&&z<=4)));
    }
    finder(0,0);finder(0,size-7);finder(size-7,0);
    for(let i=8;i<size-8;i++){if(m[6][i]===null)set(6,i,i%2===0);if(m[i][6]===null)set(i,6,i%2===0)}
    const positions=[6,28,50];
    for(const r of positions)for(const c of positions){
      if(m[r][c]!==null)continue;
      for(let y=-2;y<=2;y++)for(let z=-2;z<=2;z++)set(r+y,c+z,Math.max(Math.abs(y),Math.abs(z))!==1);
    }
    set(size-8,8,true);
    for(let i=0;i<9;i++){if(m[i][8]===null)set(i,8,false);if(m[8][i]===null)set(8,i,false)}
    for(let i=0;i<8;i++){if(m[size-1-i][8]===null)set(size-1-i,8,false);if(m[8][size-1-i]===null)set(8,size-1-i,false)}
    return m;
  }
  function masked(mask){
    const m=baseMatrix();
    let bit=0,up=true;
    for(let c=size-1;c>0;c-=2){
      if(c===6)c--;
      for(let n=0;n<size;n++){
        const r=up?size-1-n:n;
        for(let d=0;d<2;d++){
          const col=c-d;
          if(m[r][col]!==null)continue;
          const value=bit<stream.length*8?((stream[bit>>3]>>(7-(bit&7)))&1):0;
          bit++;
          const invert=[(r+col)%2===0,r%2===0,col%3===0,(r+col)%3===0,(Math.floor(r/2)+Math.floor(col/3))%2===0,(r*col)%2+(r*col)%3===0,((r*col)%2+(r*col)%3)%2===0,((r+col)%2+(r*col)%3)%2===0][mask];
          m[r][col]=Boolean(value^Number(invert));
        }
      }
      up=!up;
    }
    let format=(1<<3)|mask, v=format<<10;
    while(v.toString(2).length>=11)v^=0x537<<(v.toString(2).length-11);
    format=((format<<10)|v)^0x5412;
    for(let i=0;i<15;i++){
      const on=Boolean((format>>i)&1);
      if(i<6)m[i][8]=on;
      else if(i<8)m[i+1][8]=on;
      else m[size-15+i][8]=on;
      if(i<8)m[8][size-i-1]=on;
      else if(i<9)m[8][15-i]=on;
      else m[8][14-i]=on;
    }
    m[size-8][8]=true;
    return m;
  }
  function penalty(m){
    let score=0;
    for(let r=0;r<size;r++)for(let c=0;c<size;c++){
      let same=0;
      for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++)if((dr||dc)&&m[r+dr]?.[c+dc]===m[r][c])same++;
      if(same>5)score+=3+same-5;
    }
    for(let r=0;r<size-1;r++)for(let c=0;c<size-1;c++)if(m[r][c]===m[r+1][c]&&m[r][c]===m[r][c+1]&&m[r][c]===m[r+1][c+1])score+=3;
    for(let r=0;r<size;r++)for(let c=0;c<size-6;c++){
      const a=[];for(let k=0;k<7;k++)a.push(m[r][c+k]?1:0);
      if(a.join("")==="1011101")score+=40;
      const b=[];for(let k=0;k<7;k++)b.push(m[c+k][r]?1:0);
      if(b.join("")==="1011101")score+=40;
    }
    let dark=0;for(const row of m)for(const v of row)if(v)dark++;
    score+=Math.floor(Math.abs((dark*100/(size*size))-50)/5)*10;
    return score;
  }
  let best=masked(0),bestScore=penalty(best);
  for(let mask=1;mask<8;mask++){const candidate=masked(mask),score=penalty(candidate);if(score<bestScore){best=candidate;bestScore=score}}
  let rects='<rect width="65" height="65" fill="white"/>';
  for(let r=0;r<size;r++)for(let c=0;c<size;c++)if(best[r][c])rects+='<rect x="'+(c+4)+'" y="'+(r+4)+'" width="1" height="1"/>';
  const target=document.querySelector("#qr");
  target.innerHTML='<svg viewBox="0 0 65 65" role="img" aria-label="Authenticator setup QR code"><g fill="black">'+rects+"</g></svg>";
}

function signin(info=""){
  step(1);
  app.innerHTML="<h2>Confirm your account</h2><p>Use your bank email and password.</p>"+
    (info?note(info):"")+
    '<label for="email-input">Email address</label><input id="email-input" type="email" autocomplete="email" placeholder="name@example.com">'+
    '<label for="password-input">Password</label><input id="password-input" type="password" autocomplete="current-password">'+
    '<button class="primary" id="signin-button">Continue</button>'+help();

  document.querySelector("#signin-button").onclick=async()=>{
    const email=document.querySelector("#email-input").value;
    const password=document.querySelector("#password-input").value;
    const response=await fetch("/api/signin",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,password})});
    const data=await response.json().catch(()=>({message:"Please try again."}));
    if(!response.ok)return formMessage(data.message);
    csrf=data.csrf;
    data.mfaEnabled?account("Your authenticator is active."):setup("Your identity is confirmed. Next, add your authenticator app.");
  };
}

function setup(message){
  step(2);
  app.innerHTML="<h2>Add your authenticator app</h2>"+note(message)+
    "<p>Open your authenticator app. You can scan a setup image or copy a secret.</p>"+
    '<button class="primary" id="show-setup">Show secure setup</button>'+help();
  document.querySelector("#show-setup").onclick=provision;
}

async function provision(){
  const result=await api("/api/provision");
  if(!result.response.ok)return formMessage(result.data.message);
  secretValue=result.data.secret;uri=result.data.uri;
  if(result.data.verificationCode) testOnlyLog("Mock TOTP test value:",result.data.verificationCode);
  step(2);
  app.innerHTML="<h2>Your setup is ready</h2>"+note(result.data.message)+
    "<p>Your QR code and secret are hidden until you choose to view them.</p>"+
    '<button class="primary" id="reveal-setup">Show QR and secret</button>'+
    '<button class="secondary" id="request-setup">Request a new setup</button>'+
    '<div id="sensitive-setup" class="sensitive" hidden><p>Scan this QR code. If scanning is difficult, copy the secret below.</p><div id="qr" class="qr"></div>'+
    '<div class="secret">'+esc(secretValue)+'</div><div class="row"><button class="secondary" id="copy-secret">Copy secret</button><button class="secondary" id="hide-setup">Hide QR and secret</button></div>'+
    '<details><summary>Show full setup link</summary><div class="secret">'+esc(uri)+'</div></details><button class="primary" id="added-app">I added it to my app</button></div>'+
    '<div id="msg" class="hint"></div>'+help();

  const reveal=document.querySelector("#reveal-setup"),sensitive=document.querySelector("#sensitive-setup");
  reveal.onclick=()=>{sensitive.hidden=false;reveal.textContent="QR and secret shown";reveal.disabled=true;qr(uri)};
  document.querySelector("#request-setup").onclick=provision;
  document.querySelector("#copy-secret").onclick=()=>copy(secretValue,"Authenticator secret");
  document.querySelector("#hide-setup").onclick=()=>{sensitive.hidden=true;reveal.textContent="Show QR and secret";reveal.disabled=false};
  document.querySelector("#added-app").onclick=verifyOtp;
}

function verifyOtp(){
  step(3);
  app.innerHTML="<h2>Check your app</h2><p>Enter the six numbers shown in your authenticator app.</p>"+
    '<label for="otp-input">Six-digit code</label><input id="otp-input" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="123456">'+
    '<p class="hint">Example: 123456. You have plenty of time.</p><button class="primary" id="verify-otp">Verify code</button>'+help();
  document.querySelector("#verify-otp").onclick=async()=>{
    const otp=document.querySelector("#otp-input").value.trim();
    const result=await api("/api/verify-otp",{otp});
    if(!result.response.ok)return formMessage(result.data.message);
    codes=result.data.codes;
    if(result.data.testCodes) testOnlyLog("Mock recovery codes:",result.data.testCodes);
    saveCodes("Your authenticator is now connected.");
  };
}

function saveCodes(message){
