<section id="app" class="card" aria-live="polite"></section>
<p class="hint">Take your time. There is no reading timer.</p>
<aside class="logs" aria-label="Logs"><h2>Logs</h2><div id="logs-output">Ready.</div></aside>
</main>
<script nonce="${nonce}">
"use strict";
const app=document.querySelector("#app");
const logsOutput=document.querySelector("#logs-output");
const TEST_MOCK_LOGGING=${TEST_MOCK_LOGGING ? "true" : "false"};
let csrf="",secretValue="",uri="",codes=[];

/* Requirement: browser-console simulation mirrored to the visible Logs panel. */
function logEvent(label,value){
  if(arguments.length>1) console.log(label,value); else console.log(label);
  const line=arguments.length>1?label+" "+(Array.isArray(value)?value.join(", "):String(value)):label;
  logsOutput.textContent=(logsOutput.textContent==="Ready."?"":logsOutput.textContent+"\\n")+line;
}
function testOnlyLog(label,value){if(TEST_MOCK_LOGGING)logEvent(label,value)}
function esc(value){const el=document.createElement("span");el.textContent=String(value);return el.innerHTML}
function step(number){document.querySelectorAll("[data-s]").forEach(el=>el.classList.toggle("on",+el.dataset.s===number))}
function note(text,kind=""){return '<div class="notice '+kind+'">'+esc(text)+"</div>"}
function help(){return "<details><summary>Help with this step</summary><p>Pause or retry at any time. There is no reading timer.</p></details>"}
function formMessage(message,kind="bad"){app.insertAdjacentHTML("afterbegin",note(message,kind))}

async function api(path,data={}){
  const response=await fetch(path,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json","X-CSRF-Token":csrf},body:JSON.stringify(data)});
  const dataOut=await response.json().catch(()=>({message:"Please try again."}));
  if(response.status===401){csrf="";signin("Your session ended. Please sign in again.")}
  return {response,data:dataOut};
}
async function copy(value,name){
  const message=document.querySelector("#msg");
  try{await navigator.clipboard.writeText(value);if(message)message.textContent=name+" copied. You can paste it somewhere safe."}
  catch{if(message)message.textContent="Copy did not work in this browser. You can select the text and copy it instead."}
}

/*
 Requirement task: standards-compliant QR Code Model 2 Version 10-L encoder.
 It encodes the exact UTF-8 otpauth URI in byte mode using Version 10's
 16-bit character-count field. It generates Version 10-L Reed-Solomon blocks,
 reserves and writes format/version information, performs QR zig-zag data
 placement, evaluates all eight valid masks, and renders a four-module quiet zone.
*/
function qr(text){
  const bytes=new TextEncoder().encode(text);
  const version=10,size=57,dataCapacity=274;
  const blockSpecs=[[68,18],[68,18],[69,18],[69,18]];
  if(bytes.length>dataCapacity-3)throw new Error("Setup link is too long.");

  const exp=new Uint8Array(512),log=new Uint8Array(256);
  let field=1;
  for(let i=0;i<255;i++){exp[i]=field;log[field]=i;field<<=1;if(field&0x100)field^=0x11d}
  for(let i=255;i<512;i++)exp[i]=exp[i-255];
  const multiply=(a,b)=>a&&b?exp[log[a]+log[b]]:0;
  function generator(length){
    let polynomial=[1];
    for(let i=0;i<length;i++){
      const next=new Array(polynomial.length+1).fill(0);
      for(let j=0;j<polynomial.length;j++){next[j]^=polynomial[j];next[j+1]^=multiply(polynomial[j],exp[i])}
      polynomial=next;
    }
    return polynomial;
  }
  function ecc(data,length){
    const g=generator(length),result=new Uint8Array(length);
    for(const byte of data){
      const factor=byte^result[0];
      result.copyWithin(0,1);result[length-1]=0;
      for(let i=0;i<length;i++)result[i]^=multiply(g[i+1],factor);
    }
    return [...result];
  }

  const dataBits=[];
  const put=(value,count)=>{for(let i=count-1;i>=0;i--)dataBits.push((value>>>i)&1)};
  put(0x4,4);                 /* byte-mode indicator */
  put(bytes.length,16);       /* Version 10 byte-mode character count */
  for(const byte of bytes)put(byte,8);
  for(let i=0;i<Math.min(4,dataCapacity*8-dataBits.length);i++)dataBits.push(0);
  while(dataBits.length%8)dataBits.push(0);
  const payload=[];
  for(let i=0;i<dataBits.length;i+=8){let value=0;for(let j=0;j<8;j++)value=(value<<1)|dataBits[i+j];payload.push(value)}
  let pad=true;
  while(payload.length<dataCapacity){payload.push(pad?0xec:0x11);pad=!pad}

  const blocks=[],parity=[];
  let offset=0;
  for(const [length,ecLength] of blockSpecs){
    const part=payload.slice(offset,offset+length);offset+=length;
    blocks.push(part);parity.push(ecc(part,ecLength));
  }
  const stream=[];
  for(let i=0;i<69;i++)for(const part of blocks)if(i<part.length)stream.push(part[i]);
  for(let i=0;i<18;i++)for(const part of parity)stream.push(part[i]);

  function matrix(){
    const m=Array.from({length:size},()=>Array(size).fill(null));
    const set=(r,c,v)=>{if(r>=0&&r<size&&c>=0&&c<size)m[r][c]=Boolean(v)};
    function finder(r,c){
      for(let y=-1;y<=7;y++)for(let x=-1;x<=7;x++){
        const inside=y>=0&&y<=6&&x>=0&&x<=6;
        set(r+y,c+x,inside&&(y===0||y===6||x===0||x===6||(y>=2&&y<=4&&x>=2&&x<=4)));
      }
    }
    finder(0,0);finder(0,size-7);finder(size-7,0);
    for(let i=8;i<size-8;i++){if(m[6][i]===null)set(6,i,i%2===0);if(m[i][6]===null)set(i,6,i%2===0)}
    for(const r of [6,28,50])for(const c of [6,28,50]){
      if(m[r][c]!==null)continue;
      for(let y=-2;y<=2;y++)for(let x=-2;x<=2;x++)set(r+y,c+x,Math.max(Math.abs(y),Math.abs(x))!==1);
    }
    set(size-8,8,true);

    /* Reserve format information areas before data placement. */
    for(let i=0;i<9;i++){if(m[i][8]===null)set(i,8,false);if(m[8][i]===null)set(8,i,false)}
    for(let i=0;i<8;i++){if(m[size-1-i][8]===null)set(size-1-i,8,false);if(m[8][size-1-i]===null)set(8,size-1-i,false)}

    /* Reserve Version 10 information areas (two 3 by 6 regions). */
    for(let i=0;i<18;i++){set(Math.floor(i/3),size-11+(i%3),false);set(size-11+(i%3),Math.floor(i/3),false)}
    return m;
  }
  function bch(value,poly){
    let work=value;
    const degree=Math.floor(Math.log2(poly));
    while(work>=1<<degree)work^=poly<<(Math.floor(Math.log2(work))-degree);
    return work;
  }
  function writeFormat(m,mask){
    const raw=(1<<3)|mask; /* EC level L is binary 01 */
    const bits=((raw<<10)|bch(raw<<10,0x537))^0x5412;
    for(let i=0;i<15;i++){
      const dark=Boolean((bits>>>i)&1);
      if(i<6)m[i][8]=dark;
      else if(i<8)m[i+1][8]=dark;
      else m[size-15+i][8]=dark;
      if(i<8)m[8][size-i-1]=dark;
      else if(i<9)m[8][15-i]=dark;
      else m[8][14-i]=dark;
    }
    m[size-8][8]=true;
  }
  function writeVersion(m){
    const bits=(version<<12)|bch(version<<12,0x1f25);
    for(let i=0;i<18;i++){
      const dark=Boolean((bits>>>i)&1);
      m[Math.floor(i/3)][size-11+(i%3)]=dark;
      m[size-11+(i%3)][Math.floor(i/3)]=dark;
    }
  }
  const masked=(mask)=>{
    const m=matrix();
    let bit=0,up=true;
    for(let right=size-1;right>0;right-=2){
      if(right===6)right--;
      for(let rowIndex=0;rowIndex<size;rowIndex++){
        const r=up?size-1-rowIndex:rowIndex;
        for(let d=0;d<2;d++){
          const c=right-d;
          if(m[r][c]!==null)continue;
          const source=bit<stream.length*8?((stream[bit>>>3]>>>(7-(bit&7)))&1):0;
          bit++;
          const invert=[
            (r+c)%2===0,r%2===0,c%3===0,(r+c)%3===0,
            (Math.floor(r/2)+Math.floor(c/3))%2===0,
            ((r*c)%2+(r*c)%3)===0,
            (((r*c)%2+(r*c)%3)%2)===0,
            (((r+c)%2+(r*c)%3)%2)===0
          ][mask];
          m[r][c]=Boolean(source^Number(invert));
        }
      }
      up=!up;
    }
    writeFormat(m,mask);
    writeVersion(m);
    return m;
  };
  function score(m){
    let value=0;
    for(let r=0;r<size;r++)for(let axis=0;axis<2;axis++){
      let run=1,last=axis?m[0][r]:m[r][0];
      for(let p=1;p<size;p++){
        const current=axis?m[p][r]:m[r][p];
        if(current===last)run++;else{if(run>=5)value+=3+run-5;run=1;last=current}
      }
      if(run>=5)value+=3+run-5;
    }
    for(let r=0;r<size-1;r++)for(let c=0;c<size-1;c++)if(m[r][c]===m[r+1][c]&&m[r][c]===m[r][c+1]&&m[r][c]===m[r+1][c+1])value+=3;
    const finder="10111010000",reverse="00001011101";
    for(let r=0;r<size;r++){
      let row="",column="";
      for(let c=0;c<size;c++){row+=m[r][c]?"1":"0";column+=m[c][r]?"1":"0"}
      for(let i=0;i<=size-11;i++)if(row.slice(i,i+11)===finder||row.slice(i,i+11)===reverse)value+=40;
      for(let i=0;i<=size-11;i++)if(column.slice(i,i+11)===finder||column.slice(i,i+11)===reverse)value+=40;
    }
    let dark=0;for(const row of m)for(const module of row)if(module)dark++;
    value+=Math.floor(Math.abs(dark*100/(size*size)-50)/5)*10;
    return value;
  }
  let best=masked(0),bestScore=score(best);
  for(let mask=1;mask<8;mask++){const candidate=masked(mask),candidateScore=score(candidate);if(candidateScore<bestScore){best=candidate;bestScore=candidateScore}}
  let rects='<rect width="65" height="65" fill="white"/>';
  for(let r=0;r<size;r++)for(let c=0;c<size;c++)if(best[r][c])rects+='<rect x="'+(c+4)+'" y="'+(r+4)+'" width="1" height="1"/>';
  document.querySelector("#qr").innerHTML='<svg viewBox="0 0 65 65" role="img" aria-label="Authenticator setup QR code"><g fill="black">'+rects+"</g></svg>";
}

function signin(info=""){
  step(1);
  const testNotice=TEST_MOCK_LOGGING?note("Test mode is on. After you sign in, current mock codes are shown in Logs for reproducible testing.","success"):"";
  app.innerHTML="<h2>Confirm your account</h2><p>Use your bank email and password.</p>"+testNotice+(info?note(info):"")+
    '<label for="email-input">Email address</label><input id="email-input" type="email" autocomplete="email" placeholder="name@example.com">'+
    '<label for="password-input">Password</label><input id="password-input" type="password" autocomplete="current-password">'+
    '<button class="primary" id="signin-button">Continue</button>'+help();
  document.querySelector("#signin-button").onclick=async()=>{
    const email=document.querySelector("#email-input").value;
    const password=document.querySelector("#password-input").value;
    const response=await fetch("/api/signin",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,password})});
    const data=await response.json().catch(()=>({message:"Please try again."}));
    if(!response.ok)return formMessage(data.message);
    csrf=data.csrf;logEvent("Sign-in simulation completed.");
    data.mfaEnabled?account("Your authenticator is active."):setup("Your identity is confirmed. Next, add your authenticator app.");
  };
}

function setup(message){
  step(2);
  app.innerHTML="<h2>Add your authenticator app</h2>"+note(message)+"<p>Open your authenticator app. You can scan a setup image or copy a secret.</p>"+
    '<button class="primary" id="show-setup">Show secure setup</button>'+help();
  document.querySelector("#show-setup").onclick=provision;
}

async function provision(){
  const result=await api("/api/provision");
  if(!result.response.ok)return formMessage(result.data.message);
  secretValue=result.data.secret;uri=result.data.uri;
  logEvent("Authenticator provisioning simulation completed.");
  if(result.data.verificationCode)testOnlyLog("Mock TOTP test value:",result.data.verificationCode);
  step(2);
  app.innerHTML="<h2>Your setup is ready</h2>"+note(result.data.message)+"<p>Your QR code and secret are hidden until you choose to view them.</p>"+
    '<button class="primary" id="reveal-setup">Show QR and secret</button><button class="secondary" id="request-setup">Request a new setup</button>'+
    '<div id="sensitive-setup" class="sensitive" hidden><p>Scan this QR code. If scanning is difficult, copy the secret below.</p><div id="qr" class="qr"></div>'+
    '<div class="secret">'+esc(secretValue)+'</div><div class="row"><button class="secondary" id="copy-secret">Copy secret</button><button class="secondary" id="hide-setup">Hide QR and secret</button></div>'+
    '<details><summary>Show full setup link</summary><div class="secret">'+esc(uri)+'</div></details><button class="primary" id="added-app">I added it to my app</button></div><div id="msg" class="hint"></div>'+help();
  const reveal=document.querySelector("#reveal-setup"),sensitive=document.querySelector("#sensitive-setup");
  reveal.onclick=()=>{sensitive.hidden=false;reveal.textContent="QR and secret shown";reveal.disabled=true;qr(uri)};
  document.querySelector("#request-setup").onclick=provision;
  document.querySelector("#copy-secret").onclick=()=>copy(secretValue,"Authenticator secret");
  document.querySelector("#hide-setup").onclick=()=>{sensitive.hidden=true;reveal.textContent="Show QR and secret";reveal.disabled=false};
  document.querySelector("#added-app").onclick=verifyOtp;
}

function verifyOtp(){
  step(3);
  app.innerHTML="<h2>Check your app</h2><p>Enter the six numbers shown in your authenticator app.</p><label for="otp-input">Six-digit code</label>"+
    '<input id="otp-input" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="123456"><p class="hint">Example: 123456. You have plenty of time.</p><button class="primary" id="verify-otp">Verify code</button>'+help();
  document.querySelector("#verify-otp").onclick=async()=>{
    const otp=document.querySelector("#otp-input").value.trim();
    const result=await api("/api/verify-otp",{otp});
    if(!result.response.ok)return formMessage(result.data.message);
    codes=result.data.codes;logEvent("Authenticator verification simulation succeeded.");
    if(result.data.testCodes)testOnlyLog("Mock recovery codes:",result.data.testCodes);
    saveCodes("Your authenticator is now connected.");
  };
}

function saveCodes(message){
  step(4);
  app.innerHTML="<h2>Save your recovery codes</h2>"+note(message,"success")+"<p>Store these somewhere safe. Each code works once.</p><div class=\\"codes\\">"+
    codes.map(code=>'<div class="code">'+esc(code)+"</div>").join("")+"</div><button class=\\"secondary\\" id=\\"copy-all\\">Copy all recovery codes</button><div id=\\"msg\\" class=\\"hint\\"></div><button class=\\"primary\\" id=\\"saved-codes\\">I saved my codes</button>"+help();
  document.querySelector("#copy-all").onclick=()=>copy(codes.join("\\n"),"All recovery codes");
  document.querySelector("#saved-codes").onclick=()=>account("Your recovery codes are saved.");
}

function recoveryVerification(message="",kind=""){
  step(4);
  app.innerHTML="<h2>Use a recovery code</h2>"+(message?note(message,kind):"")+"<p>Use one saved recovery code when you need to check that it works.</p>"+
    '<label for="recovery-code-input">Recovery code</label><input id="recovery-code-input" inputmode="text" autocomplete="one-time-code" autocapitalize="characters" maxlength="11" placeholder="AAAAA-BBBBB" aria-describedby="recovery-example">'+
    '<p id="recovery-example" class="hint">Example: AAAAA-BBBBB</p><button class="primary" id="verify-recovery-code">Verify recovery code</button><button class="secondary" id="back-account">Back to security setup</button>'+help();
  const input=document.querySelector("#recovery-code-input");
  input.addEventListener("input",()=>{input.value=input.value.toUpperCase().replace(/[^A-Z0-9-]/g,"").slice(0,11)});
  document.querySelector("#back-account").onclick=()=>account("Your authenticator is active.");
  document.querySelector("#verify-recovery-code").onclick=async()=>{
    const code=input.value.trim();
    const result=await api("/api/verify-recovery-code",{code});
    if(result.response.ok)logEvent("Recovery-code verification simulation succeeded.");
    recoveryVerification(result.data.message,result.response.ok?"success":"bad");
  };
}

function account(message){
  step(4);
  app.innerHTML="<h2>Security setup</h2>"+note(message,"success")+"<p>Your authenticator is active.</p><button class="primary" id="use-recovery">Use a recovery code</button>"+
    '<button class="secondary" id="replace-authenticator">Replace authenticator</button><button class="secondary" id="new-recovery-codes">Generate new recovery codes</button><button class="secondary" id="sign-out">Sign out</button>'+help();
  document.querySelector("#use-recovery").onclick=()=>recoveryVerification();
  document.querySelector("#replace-authenticator").onclick=async()=>{const result=await api("/api/begin-reenrolment");result.response.ok?setup("Replacement started. Your current authenticator remains active until checked."):formMessage(result.data.message)};
  document.querySelector("#new-recovery-codes").onclick=async()=>{
    const result=await api("/api/regenerate-backup-codes");
    if(result.response.ok){codes=result.data.codes;logEvent("Recovery-code generation simulation completed.");if(result.data.testCodes)testOnlyLog("Mock recovery codes:",result.data.testCodes);saveCodes("New recovery codes replaced the old ones.")}
    else formMessage(result.data.message);
  };
  document.querySelector("#sign-out").onclick=async()=>{await api("/api/logout");csrf="";logEvent("Sign-out simulation completed.");signin("You have signed out safely.")};
}
signin();
</script>
</body>
</html>`;
}

async function recoveryFailure(request: Request, account: any, message: string) {
  account.recoveryFailures++;
  if (account.recoveryFailures >= MAX_FAILURES) {
    account.recoveryLocked = Date.now() + LOCKOUT;
    return json(request, { ok: false, locked: true, message: "Too many recovery-code attempts. Recovery verification is locked for five minutes. You can try again after that." }, 429);
  }
  const remaining = MAX_FAILURES - account.recoveryFailures;
  return json(request, { ok: false, locked: false, message: `${message} Please try again. ${remaining} attempt${remaining === 1 ? "" : "s"} remain before a short lockout.` }, 400);
}

async function handle(request: Request): Promise<Response> {
  const url = new URL(request.url);
  if (url.protocol !== "https:" || !trusted(url.hostname)) return new Response("Not found", { status: 404, headers: headers(request) });

  if (request.method === "GET" && url.pathname === "/") {
    const nonce = token(18);
    const output = headers(request, nonce);
    output.set("Content-Type", "text/html; charset=utf-8");
    return new Response(page(nonce), { headers: output });
  }

  if (request.method === "POST" && url.pathname === "/api/signin") {
    if (!originOK(request)) return json(request, { ok: false, message: "Please use the secure sign-in page." }, 403);
    const data = await body(request);
    const email = typeof data?.email === "string" ? data.email.toLowerCase().trim() : "";
    const password = data?.password;
    const account = [...accounts.values()].find(value => value.email === email);
    const matches = same(sha256(typeof password === "string" ? password : ""), account ? account.passwordHash : dummyPasswordHash);
    if (!account || !matches || !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email) || typeof password !== "string" || password.length < 8) {
      return json(request, { ok: false, message: "Sign-in could not be completed. Check your email and password, then try again." }, 401);
    }
    /* Requirement 5: rotate session on authentication. */
    for (const [id, session] of sessions) if (session.userId === account.id) sessions.delete(id);
    const id = token();
    const session = { userId: account.id, csrf: token(24), createdAt: Date.now(), lastSeenAt: Date.now() };
    sessions.set(id, session);
    return json(request, { ok: true, csrf: session.csrf, mfaEnabled: account.mfaEnabled }, 200, { "Set-Cookie": sessionCookie(id) });
  }

  const current = owner(request);
  if (!current) return json(request, { ok: false, message: "Please sign in again to continue." }, 401);
  if (request.method !== "POST" || !csrf(request, current.session)) return json(request, { ok: false, message: "Please refresh the secure page and try again." }, 403);
  const account = current.account;

  if (url.pathname === "/api/logout") {
    sessions.delete(current.id);
    return json(request, { ok: true }, 200, { "Set-Cookie": "mfa_session=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0" });
  }

  if (url.pathname === "/api/begin-reenrolment") {
    if (!account.mfaEnabled) return json(request, { ok: false, message: "Finish setup first." }, 400);
    account.replacing = true;
    return json(request, { ok: true });
  }

  if (url.pathname === "/api/provision") {
    if (account.mfaEnabled && !account.replacing) return json(request, { ok: false, message: "Choose Replace authenticator first." }, 400);
    const sharedSecret = secret();
    account.pending = await encrypt(sharedSecret);
    account.pendingUsed = [];
    const uri = "otpauth://totp/" + encodeURIComponent("Northstar Bank:" + account.email) + "?secret=" + sharedSecret + "&issuer=Northstar%20Bank&algorithm=SHA1&digits=6&period=30";
    const response: any = { ok: true, secret: sharedSecret, uri, message: "Authenticator setup is ready." };
    if (TEST_MOCK_LOGGING) response.verificationCode = await totp(sharedSecret);
    return json(request, response);
  }

  if (url.pathname === "/api/verify-otp") {
    const data = await body(request);
    const now = Date.now();
    if (!validOtp(data?.otp)) return json(request, { ok: false, message: "Enter exactly six numbers, for example 123456." }, 400);
    if (account.otpLocked > now) return json(request, { ok: false, message: "Too many attempts. Please wait a few minutes." }, 429);

    /* Task: an expired lockout restores the full five-attempt OTP window. */
    if (account.otpLocked && account.otpLocked <= now) {
      account.otpLocked = 0;
      account.otpFailures = 0;
    }

    if (!account.pending) return json(request, { ok: false, message: "Request a new setup and try again." }, 400);
    const sharedSecret = await decrypt(account.pending);
    const base = Math.floor(now / 30_000);
    let hit = -1;
    for (let counter = base - 1; counter <= base + 1; counter++) {
      if (counter >= 0 && !account.pendingUsed.includes(counter) && same(await totp(sharedSecret, counter), data.otp)) { hit = counter; break; }
    }
    if (hit < 0) {
      if (++account.otpFailures >= MAX_FAILURES) account.otpLocked = now + LOCKOUT;
      return json(request, { ok: false, message: "That code did not match, was used, or is no longer current. Try again." }, 400);
    }
    account.pendingUsed.push(hit);
    account.active = account.pending;
    account.pending = null;
    account.mfaEnabled = true;
    account.replacing = false;
    account.otpFailures = 0;
    account.otpLocked = 0;
    const codes = recoveryCodes();
    account.backup = await Promise.all(codes.map(code => hmac(code, recoveryKey)));
    account.usedBackup = [];
    account.recoveryFailures = 0;
    account.recoveryLocked = 0;
    const response: any = { ok: true, codes };
    if (TEST_MOCK_LOGGING) response.testCodes = codes;
    return json(request, response);
  }

  if (url.pathname === "/api/regenerate-backup-codes") {
    if (!account.mfaEnabled) return json(request, { ok: false, message: "Finish setup first." }, 400);
    const codes = recoveryCodes();
    account.backup = await Promise.all(codes.map(code => hmac(code, recoveryKey)));
