    const now = Date.now();
    if (account.recoveryLocked > now) {
      return json(request, { ok: false, locked: true, message: "Recovery verification is locked for five minutes after too many attempts. Please try again later." }, 429);
    }

    /* Task: an expired recovery lockout restores the full five-attempt window. */
    if (account.recoveryLocked && account.recoveryLocked <= now) {
      account.recoveryLocked = 0;
      account.recoveryFailures = 0;
    }

    const data = await body(request);
    if (!validRecoveryCode(data?.code)) return recoveryFailure(request, account, "Use five capital letters or numbers, a hyphen, then five more. Example: AAAAA-BBBBB.");
