  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let output = "";
  for (let i = 0; i < 10; i++) {
    if (i === 5) output += "-";
    output += alphabet[secureInt(alphabet.length)];
